  static void EditedRegressions(){
   Test("Repeated Edited imports add checked images and preserve unchecked existing images",()=>{
    string source=Path.Combine(root,"edited-repeat-source"),old=Path.Combine(source,"M31_starless.fit"),fresh=Path.Combine(source,"M51_stars.fit"),excluded=Path.Combine(source,"Moon.fit");Write(old,64,48,(x,y)=>1300,new Dictionary<string,string>());
    using(var repo=new Repository(Path.Combine(root,"edited-repeat-repo"))){var first=repo.ImportEditedFolder(repo.ScanEditedFolder(source,true,ct,NoProgress),"Older import",ct,NoProgress);string saved=repo.EditedPath(first,first.Sources.Single().RelativePath),manifest=Path.Combine(repo.EditedProjectFolder(first),"edited-project.json"),before=File.ReadAllText(manifest),hash=Util.Hash(saved,ct);
     Write(fresh,64,48,(x,y)=>2100,new Dictionary<string,string>());Write(excluded,64,48,(x,y)=>2500,new Dictionary<string,string>());var plan=repo.ScanEditedFolder(source,true,ct,NoProgress);Check(plan.Images.Single(i=>i.Path==old).AlreadyImported&&!plan.Images.Single(i=>i.Path==old).Include,"Existing duplicate was checked by default");plan.Images.Single(i=>i.Path==excluded).Include=false;var added=repo.ImportEditedFolder(plan,"New import",ct,NoProgress);List<string> errors;var projects=repo.EditedProjects(out errors);Check(projects.SelectMany(p=>repo.EditedImages(p)).Count()==2&&repo.EditedImages(added).Single().Filename=="M51_stars.fit"&&File.ReadAllText(manifest)==before&&Util.Hash(saved,ct)==hash&&File.Exists(excluded),"Import hid/deleted an old file or imported unchecked files");
     var none=repo.ScanEditedFolder(source,true,ct,NoProgress);foreach(var row in none.Images)row.Include=false;Expect(()=>repo.ImportEditedFolder(none,"Empty",ct,NoProgress),"Unchecked-only import succeeded");Check(repo.EditedProjects(out errors).Count==2&&Util.Hash(saved,ct)==hash,"Unchecked-only import touched existing images");
     plan=repo.ScanEditedFolder(source,true,ct,NoProgress);foreach(var row in plan.Images)row.Include=row.Path==old;repo.ImportEditedFolder(plan,"Explicit duplicate",ct,NoProgress);Check(repo.EditedProjects(out errors).SelectMany(p=>repo.EditedImages(p)).Count()==3&&Util.Hash(saved,ct)==hash,"Explicit duplicate overwrote an existing image");
     plan=repo.ScanEditedFolder(source,true,ct,NoProgress);foreach(var row in plan.Images)row.Include=row.Path==excluded;File.AppendAllText(excluded,"changed");Expect(()=>repo.ImportEditedFolder(plan,"Failed",ct,NoProgress),"Stale new import accepted");Check(repo.EditedProjects(out errors).Count==3&&File.ReadAllText(manifest)==before,"Failed new import removed earlier images");
    }
   });
