     repo.SaveEditedMetadata(project,new[]{row},new EditedMetadata{ImageClass="Stars only"},ct);Write(saved,64,48,(x,y)=>2300,new Dictionary<string,string>{{"SUBEXP","'90'"},{"NCOMBINE","'20'"}});string output=Path.Combine(Path.GetDirectoryName(saved),"M51_starless.fit");Write(output,64,48,(x,y)=>3100,new Dictionary<string,string>());project=repo.EditedProjects(out errors).Single();var outputRow=repo.EditedImages(project).Single(i=>i.Filename=="M51_starless.fit");repo.SaveEditedMetadata(project,new[]{outputRow},new EditedMetadata{TotalExposure=4200},ct);project=repo.EditedProjects(out errors).Single();row=repo.EditedImages(project).Single(i=>i.RelativePath==row.RelativePath);Check(row.Metadata.SubExposure==90&&row.Metadata.ImageClass=="Stars only"&&row.Metadata.TotalExposure==1800&&row.Metadata.Filters=="L, Ha","Patch froze inferred fields or lost an earlier assignment");
